from typing import Optional, Union, Sequence, Callable, Any

class Tensor:
    def __init__(self, data: Union[float, int, list], requires_grad: bool = False):
        self.data = self._to_nested_float(data)
        self.requires_grad = requires_grad
        self.grad: Optional[Any] = None
        self._prev: set[Tensor] = set()
        self._backward: Callable[[], None] = lambda: None

    def _to_nested_float(self, d: Any) -> Any:
        if isinstance(d, (int, float)):
            return float(d)
        return [self._to_nested_float(x) for x in d]

    def __add__(self, other: Union[Tensor, float, int]) -> Tensor:
        other_t = other if isinstance(other, Tensor) else Tensor(other)
        out = Tensor(self.data + other_t.data, requires_grad=self.requires_grad or other_t.requires_grad)
        out._prev = {self, other_t}
        def _back():
            if self.requires_grad:
                self.grad = (self.grad or 0.0) + out.grad
            if other_t.requires_grad:
                other_t.grad = (other_t.grad or 0.0) + out.grad
        out._backward = _back
        return out

    def __radd__(self, other: Union[float, int]) -> Tensor:
        return self.__add__(other)

    def __mul__(self, other: Union[Tensor, float, int]) -> Tensor:
        other_t = other if isinstance(other, Tensor) else Tensor(other)
        out = Tensor(self.data * other_t.data, requires_grad=self.requires_grad or other_t.requires_grad)
        out._prev = {self, other_t}
        def _back():
            if self.requires_grad:
                self.grad = (self.grad or 0.0) + other_t.data * out.grad
            if other_t.requires_grad:
                other_t.grad = (other_t.grad or 0.0) + self.data * out.grad
        out._backward = _back
        return out

    def __rmul__(self, other: Union[float, int]) -> Tensor:
        return self.__mul__(other)

